shots.draw_js:
clearScene();setBig(null);setEq(null);
lamps({y:290,gap:290,items:[
  {label:"金融",sub:"每次部署都是真钱",state:"dead"},
  {label:"医疗",sub:"病人只有一次",state:"dead"},
  {label:"线上系统",sub:"客户会流失",state:"dead"}]});
note("这些地方不能「先试试」",640,430,"r");
setCap("在这些场景里，<b>每一次把新策略推上线，都是一次不可撤销的代价</b>。");

clearScene();setEq(null);
setBig("震荡一下没关系","反正最后会收敛");
setCap("「最终收敛」和「每一步都不变差」<b>是两个完全不同的要求</b>。");

clearScene();setBig(null);
setEq("$$V^{\\pi_{i+1}}(s)\\ \\ge\\ V^{\\pi_i}(s)\\qquad \\forall s$$","top");
note("对每一个状态都成立",640,310,"g lg");
setCap("把目标写死：<b>逐状态</b>不变差，不是平均意义上不变差。");

clearScene();setBig(null);setEq(null);
note("L9：恒等式不可算",360,260,"r lg","start");
note("L9：代理目标可算",360,340,"g lg","start");
note("L10：把最后一步走完",360,420,"y lg","start");
setCap("L9 铺了两块砖，<b>第三块在这一讲</b>。");

clearScene();setBig(null);setEq(null);
note("最终收敛",400,290,"sm lg");
note("每步不变差",880,290,"g lg");
note("后者严格更强",640,400,"y lg");
setCap("<b>指名反驳</b>：要的不是收敛，是<b>逐步、逐状态</b>都不变差。");

clearScene();setBig(null);
setEq("$$\\pi_{\\text{new}}=(1-\\alpha)\\pi_{\\text{old}}+\\alpha\\pi'$$","top");
note("CPI 界要求这个形状",640,310,"r lg");
setCap("L9 引的那条界有一个限制：新策略必须是一个<b>混合</b>策略。");

clearScene();setEq(null);
setBig("有 CPI 就够了","界已经有了，直接用就是");
setCap("形状对不上：<b>梯度更新出来的策略不是混合策略</b>。");

clearScene();setBig(null);
setEq("$$V(\\pi_{\\text{new}})\\ \\ge\\ L(\\pi_{\\text{new}})-\\frac{4\\varepsilon\\gamma}{(1-\\gamma)^2}\\,D_{TV}^{\\max}(\\pi_{\\text{old}},\\pi_{\\text{new}})^2$$","top");
note("对任意随机策略成立",640,320,"g lg");
setCap("一般下界：<b>代理目标 减去 一个随距离增长的惩罚</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:360,items:[
  {label:"CPI 的 ε",sub:"动作先取期望",state:"on"},
  {label:"一般界的 ε",sub:"状态动作都取 max",state:"dead"}]});
note("后者不小于前者",640,420,"y");
setCap("推广的代价全在 ε 上：从<b>动作取期望后的最大</b>，变成<b>状态动作都取最大</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"CPI",sub:"只对混合策略",state:"dead"},
  {label:"一般界",sub:"任意随机策略",state:"on"},
  {label:"但 ε 变大了",sub:"max_{s,a}|A|",state:"dead"}]});
note("推广不是免费的",640,420,"y");
setCap("<b>指名反驳</b>：CPI 套不上梯度更新。推广版能用 —— <b>但 ε 更大</b>。");

clearScene();setBig(null);
setEq("$$D_{TV}(p,q)\\ \\overset{?}{=}\\ \\max_a|p(a)-q(a)|$$","top");
note("板上是这么写的",640,300,"r lg");
note("标准定义不是这个",640,360,"y lg");
setCap("界里那个距离，<b>板上写的是 L∞</b>，而全变差距离的标准定义不是它。");

clearScene();setEq(null);
setBig("取 max 和取 ½L1 差不多","反正都是衡量两个分布差多远");
setCap("在<b>两个动作</b>时它们<b>完全相等</b> —— 这正是它难被发现的原因。");

clearScene();setBig(null);
setEq("$$\\textstyle\\sum_a\\big(p(a)-q(a)\\big)=0 \\ \\Longrightarrow\\ \\text{正差之和}=\\text{负差之和}=\\tfrac12 L_1$$","top");
note("只有一个分量上升时",640,310,"y lg");
note("L∞ 恰好等于那个和",640,370,"g lg");
setCap("两者相等的<b>充分条件</b>：只有<b>一个</b>分量上升（或只有一个下降）。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[0.30,0.60],
  x:380,y:430,w:520,h:170,max:0.7,
  label:function(i){return ["L∞（板上）","½L1（标准）"][i];},
  cls:function(i){return i===0?"r":"g";},
  fmt:function(v){return v.toFixed(2);}});
note("四动作，两个分量上升",640,466,"y");
setCap("反例：p=(.4,.4,.1,.1) → q=(.1,.1,.4,.4)，<b>0.30 对 0.60，差一倍</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"两动作",sub:"两者相等",state:"on"},
  {label:"多动作",sub:"可以差一倍",state:"dead"},
  {label:"惩罚里是平方",sub:"实际差四倍",state:"dead"}]});
note("而且偏向不安全那侧",640,420,"r");
setCap("<b>指名反驳</b>：只在两动作时相等。多动作时 <b>L∞ 偏小</b>，惩罚被低估。");
